function glow(size) {
  return size * 20 + 10;
}

export const lanternSmall = glow(2);
export const lanternMedium = glow(4);
export const lanternBig = glow(6);

export function treantPhase(health) {
  if (health > 60) {
    return "calm";
  } else {
    return "angry";
  }
}

export function treantPhase(health) {
  if (health > 60) {
    return "calm";
  } else if (health > 30) {
    return "angry";
  } else {
    return "giant";
  }
}

function isDanger(health) {
  return health <= 30;
}

export function treantPhase(health) {
  if (isDanger(health)) {
    return "giant";
  } else if (health > 60) {
    return "calm";
  } else {
    return "angry";
  }
}

export function treantSays(phase) {
  if (phase === "giant") {
    return "Я ВЫРОС!";
  } else if (phase === "angry") {
    return "Уходи из леса!";
  } else {
    return "Тише...";
  }
}
